import{calculator,CalcError,has,pos,num,pick,dflt}from './core.js?ver=467cb2c42a';
export function priceRange(d,type,kwp){const rows=(d?.solar_prices?.systems||[]).filter((r)=>r.type===type&&r.kw>0).sort((a,b)=>a.kw-b.kw);if(!rows.length)throw new CalcError('price_data_missing','type');const perW=(r)=>({lo:r.low_rs/(r.kw*1000),hi:r.high_rs/(r.kw*1000)});const weak=(...rs)=>({low_confidence:rs.some((r)=>(r.n_sources??0)<2)});const exact=rows.find((r)=>Math.abs(r.kw-kwp)<1e-9);if(exact)return{...perW(exact),range_kw_used:exact.kw,...weak(exact)};if(kwp<=rows[0].kw)return{...perW(rows[0]),range_kw_used:rows[0].kw,low_confidence:true};const last=rows[rows.length-1];if(kwp>=last.kw)return{...perW(last),range_kw_used:last.kw,low_confidence:true};const a=rows.filter((r)=>r.kw<kwp).pop();const b=rows.find((r)=>r.kw>kwp);const t=(kwp-a.kw)/(b.kw-a.kw);const w=kwp*1000;return{lo:(a.low_rs+(b.low_rs-a.low_rs)*t)/w,hi:(a.high_rs+(b.high_rs-a.high_rs)*t)/w,range_between_kw:[a.kw,b.kw],...weak(a,b)};}
export function inverterAt(items,category,kw,bv){const rows=items.filter((x)=>x.category===category&&x.export_capable !==false&&(!bv||x.bank_v===bv)).map((x)=>({kw:parseFloat(x.size),rs:(x.low+x.high)/2,w:(x.n_sources??0)<2})).sort((a,b)=>a.kw-b.kw);const a=rows.filter((r)=>r.kw<=kw).pop()||rows[0];const b=rows.find((r)=>r.kw>kw);const v=!b||kw<=a.kw?(a.rs/a.kw)*kw:a.rs+((b.rs-a.rs)*(kw-a.kw))/(b.kw-a.kw);return[v,a.w||Boolean(b?.w&&kw>a.kw),kw>rows[rows.length-1].kw];}
export function hybridPremium(items,kw,backup_kw,v){const hkw=Math.max(kw,backup_kw);const[hy,hw,above]=inverterAt(items,'hybrid_inverter',hkw,v);const[on,ow]=inverterAt(items,'ongrid_inverter',kw);return[Math.max(0,hy-on),hy-on>1e-9,hw||ow,above,hkw];}
export function rank(xs){if(!xs.length)return[];const best=(a,b)=>(b.net_rs<a.net_rs-1e-9||(Math.abs(b.net_rs-a.net_rs)<=1e-9&&b.buy<a.buy)?b:a);const pick=xs.reduce(best);const rest=xs.filter((x)=>x !==pick);const ru=rest.length?rest.reduce(best):null;return[pick,ru,Boolean(ru&&ru.key !=='grid'&&pick.key !=='grid'&&ru.lo<=pick.hi+1e-9&&pick.lo<=ru.hi+1e-9)];}
export const quote_checker=calculator((i,d)=>{const kwp=pos(i,'kwp');const price=pos(i,'price');const rs_per_w=price/(kwp*1000);const out={kwp,price,rs_per_w};let lo;let hi;if(has(i,'range_low')||has(i,'range_high')){lo=pos(i,'range_low');hi=pos(i,'range_high');out.range_source='input';}else if(has(i,'type')){const type=pick(i,'type',['on-grid','hybrid']);const r=priceRange(d,type,kwp);({lo,hi}=r);Object.assign(out,{type,range_source:'data',low_confidence:r.low_confidence},r.range_kw_used !==undefined?{range_kw_used:r.range_kw_used}:{range_between_kw:r.range_between_kw});}
if(lo !==undefined){if(lo>hi)throw new CalcError('range_invalid','range_low');Object.assign(out,{range_low:lo,range_high:hi,range_low_rs:lo*kwp*1000,range_high_rs:hi*kwp*1000,verdict:rs_per_w<lo?'below':rs_per_w>hi?'above':'within',vs_low_pct:((rs_per_w-lo)/lo)*100,vs_high_pct:((rs_per_w-hi)/hi)*100});}
return out;},{allowNegative:['vs_low_pct','vs_high_pct']});
export const solar_price_estimate=calculator((i,d)=>{const kwp=pos(i,'kwp');const type=pick(i,'type',['on-grid','hybrid'],'on-grid');const r=priceRange(d,type,kwp);const out={kwp,type,system_w:kwp*1000,rs_per_w_low:r.lo,rs_per_w_high:r.hi,price_low_rs:r.lo*kwp*1000,price_high_rs:r.hi*kwp*1000,price_mid_rs:((r.lo+r.hi)/2)*kwp*1000};if(r.range_kw_used !==undefined)out.range_kw_used=r.range_kw_used;else out.range_between_kw=r.range_between_kw;out.low_confidence=r.low_confidence;const panel=d?.solar_prices?.panel_rs_per_w;if(panel?.low>0&&panel?.high>0)Object.assign(out,{panel_rs_per_w_low:panel.low,panel_rs_per_w_high:panel.high,panels_low_rs:kwp*1000*panel.low,panels_high_rs:kwp*1000*panel.high});if(has(i,'monthly_saving_rs')){const monthly_saving_rs=pos(i,'monthly_saving_rs');Object.assign(out,{monthly_saving_rs,payback_years_low:out.price_low_rs/(monthly_saving_rs*12),payback_years_high:out.price_high_rs/(monthly_saving_rs*12)});}
return out;});
export const panel_price=calculator((i,d)=>{const p=d?.solar_prices?.panel_rs_per_w;if(!(p?.low>0)||!(p?.high>=p.low))throw new CalcError('price_data_missing','panel_w');const panel_w=pos(i,'panel_w',dflt(d,'panel_w'));const panels=num(i,'panels',{min:1});if(!Number.isInteger(panels))throw new CalcError('panels_must_be_whole','panels');const kw=(panel_w*panels)/1000;return{panel_w,panels,kw,rs_per_w_low:p.low,rs_per_w_high:p.high,panel_low_rs:panel_w*p.low,panel_high_rs:panel_w*p.high,total_low_rs:panel_w*panels*p.low,total_high_rs:panel_w*panels*p.high};});
